using System;
using System.Linq;
using UnityEngine;
namespace CafeLife {
 public static class CafeDeliveryChecks {
  public static string Report="";static void Check(bool ok,string name){if(!ok)throw new Exception(name);Report+="PASS "+name+"\n";}
  public static void Validate(CafeGame g){Report="";g.Continue();g.Discard();foreach(var d in g.shelf)if(d.visual)UnityEngine.Object.Destroy(d.visual);g.shelf.Clear();var created=new System.Collections.Generic.List<CafeCustomer>();for(int i=0;i<2;i++){g.Spawn();var c=g.customers.Last();c.state=CafeCustomer.State.Waiting;c.recipe=0;created.Add(c);}var a=new PreparedDrink{cup=new CupWork{recipe=0,brewed=true,lidded=true},good=true};a.visual=g.world.PlaceStaffCup(a.cup,0);var b=new PreparedDrink{cup=new CupWork{recipe=1,hasMilk=true,brewed=true,lidded=true},good=true};b.visual=g.world.PlaceStaffCup(b.cup,1);g.shelf.Add(a);g.shelf.Add(b);Check(g.TryMatchShelf(created[0])&&a.owner==created[0]&&created[0].state==CafeCustomer.State.ToPickup,"Espresso reservation belongs to matching customer");Check(created[0].accepted&&created[0].orderNumber>0&&a.visual.GetComponentsInChildren<TextMesh>().Any(t=>t.text.StartsWith("#"+created[0].orderNumber)),"Reserved cup displays assigned order number");Check(!g.TryMatchShelf(created[1])&&b.owner==null,"Second customer cannot claim reserved cup or different recipe");var cdrink=new PreparedDrink{cup=new CupWork{recipe=0,brewed=true,lidded=true},good=true};cdrink.visual=g.world.PlaceStaffCup(cdrink.cup,2);g.shelf.Add(cdrink);Check(g.TryMatchShelf(created[1])&&cdrink.owner==created[1]&&a.owner==created[0],"Two identical recipes retain distinct reservations");a.age=120;b.age=120;g.expansion.ClearStale();Check(g.shelf.Contains(a)&&!g.shelf.Contains(b),"Stale cleanup preserves customer-reserved drink");g.TakeReservedDrink(created[1]);Check(!g.shelf.Contains(cdrink)&&g.shelf.Contains(a),"Collection removes only customer's own reserved cup");g.TakeReservedDrink(created[1]);Check(g.shelf.Count==1,"Repeated collection cannot consume another reservation");g.TakeReservedDrink(created[0]);Check(g.shelf.Count==0,"Both reservations can be collected independently");foreach(var c in created){g.customers.Remove(c);UnityEngine.Object.Destroy(c.gameObject);}g.Tell("");
  }
 }
}
